@push('scripts')<script>document.querySelectorAll('.request-status').forEach(function(select){select.addEventListener('change',function(){const control=this;control.disabled=true;fetch(control.dataset.url,{method:'PATCH',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({status:control.value})}).then(response=>{if(!response.ok)throw new Error();return response.json()}).then(()=>{control.classList.add('border-success');setTimeout(()=>control.classList.remove('border-success'),1200)}).catch(()=>{alert('Status update failed. Please try again.');location.reload()}).finally(()=>{control.disabled=false})})});</script>@endpush
